class Solution {
    public String decodeAtIndex(String s,int k){
        long size=0;
        for(char c:s.toCharArray())if(Character.isDigit(c))size*=c-'0';
        else size++;
        long index=k;
        for(int i=s.length()-1;i>=0;i--){
            char c=s.charAt(i);
            if(Character.isDigit(c))size/=c-'0';
            else{
                if(index%size==0)return Character.toString(c);
                size--;
            }
        }
        return "";
    }
}

code.kotlin:
class Solution {
    fun decodeAtIndex(s:String,k:Int):String{
        var size=0L;
        for(c in s)if(c.isDigit())size*=c-'0' else size++;
        val index=k.toLong();
        for(i in s.indices.reversed()){
            val c=s[i];
            if(c.isDigit())size/=c-'0' else{
                if(index%size==0L)return c.toString();
                size--
            }
        };
        return ""
    }
}

